```js
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);
  if (value instanceof Date) return new Date(value);
  if (value instanceof RegExp) return new RegExp(value.source, value.flags);
  if (value instanceof Map) {
    const result = new Map();
    seen.set(value, result);
    for (const [k, v] of value) result.set(deepClone(k, seen), deepClone(v, seen));
    return result;
  }
  if (value instanceof Set) {
    const result = new Set();
    seen.set(value, result);
    for (const v of value) result.add(deepClone(v, seen));
    return result;
  }
  const result = Array.isArray(value) ? [] : {};
  seen.set(value, result);
  for (const k of Object.keys(value)) result[k] = deepClone(value[k], seen);
  return result;
}
```
Note: doesn't handle functions, Symbols, getters/setters — flag this if asked.

```js
class EventEmitter {
  constructor() { this.events = new Map(); }
  on(event, fn) {
    if (!this.events.has(event)) this.events.set(event, new Set());
    this.events.get(event).add(fn);
    return () => this.off(event, fn);  // return unsubscribe
  }
  off(event, fn) {
    this.events.get(event)?.delete(fn);
  }
  emit(event, ...args) {
    this.events.get(event)?.forEach(fn => fn(...args));
  }
  once(event, fn) {
    const wrapper = (...args) => { fn(...args); this.off(event, wrapper); };
    this.on(event, wrapper);
  }
}
```

```js
function memoize(fn, keyFn = (...args) => JSON.stringify(args)) {
  const cache = new Map();
  return function(...args) {
    const key = keyFn(...args);
    if (!cache.has(key)) cache.set(key, fn.apply(this, args));
    return cache.get(key);
  };
}
```
Caveats: JSON.stringify breaks on circular refs and doesn't distinguish e.g. `undefined` from missing. Use a custom keyFn for production.

```js
class LRUCache {
  constructor(max) {
    this.max = max;
    this.cache = new Map();
  }
  get(key) {
    if (!this.cache.has(key)) return undefined;
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);  // re-insert as most recent
    return value;
  }
  set(key, value) {
    if (this.cache.has(key)) this.cache.delete(key);
    else if (this.cache.size >= this.max) {
      this.cache.delete(this.cache.keys().next().value);  // evict oldest
    }
    this.cache.set(key, value);
  }
}
```
O(1) get and set. Trick: Map preserves insertion order, so the first key is the oldest.

```js
Array.prototype.myReduce = function(callback, initialValue) {
  let acc;
  let startIndex = 0;
  if (arguments.length >= 2) {
    acc = initialValue;
  } else {
    if (this.length === 0) throw new TypeError('Reduce of empty array with no initial value');
    acc = this[0];
    startIndex = 1;
  }
  for (let i = startIndex; i < this.length; i++) {
    if (i in this) acc = callback(acc, this[i], i, this);
  }
  return acc;
};
```
Subtle: `i in this` handles sparse arrays. No initial value + empty array throws.

```js
class Subject {
  constructor() { this.observers = new Set(); }
  subscribe(observer) {
    this.observers.add(observer);
    return () => this.observers.delete(observer);
  }
  next(value) { this.observers.forEach(o => o.next?.(value)); }
  error(err) { this.observers.forEach(o => o.error?.(err)); }
  complete() {
    this.observers.forEach(o => o.complete?.());
    this.observers.clear();
  }
}
```
Observer shape: `{ next?, error?, complete? }`. Cold vs hot observables: hot starts emitting regardless of subscription; cold starts per subscription.

