function useDebounce(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debouncedValue;
}
```

```js
function useOnClickOutside(ref, handler) {
  useEffect(() => {
    function listener(e) {
      if (!ref.current || ref.current.contains(e.target)) return;
      handler(e);
    }
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchstart', listener);
    };
  }, [ref, handler]);
}
```
Edge case: portals render outside the ref's DOM tree — they'll register as 'outside'. Handle with a closer ref or a class-based check.

```js
function useIntersectionObserver(ref, options = {}) {
  const [isIntersecting, setIsIntersecting] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const observer = new IntersectionObserver(
      ([entry]) => setIsIntersecting(entry.isIntersecting),
      options
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref, options.threshold, options.rootMargin, options.root]);
  return isIntersecting;
}
```
Note: passing `options` object directly causes re-observe on every render. Destructure dep array.

ANSWER: `useOptimistic` lets you immediately show an optimistic state while an async action is in flight. Signature: `const [optimisticState, addOptimistic] = useOptimistic(state, updateFn)`. While a transition runs, the optimistic state shows the predicted result; when the action completes, React reverts to the real state. Example:
```js
const [optimisticMessages, addOptimisticMessage] = useOptimistic(
  messages,
  (state, newMessage) => [...state, { ...newMessage, sending: true }]
);
async function send(text) {
  addOptimisticMessage({ text, id: uuid() });
  await api.send(text);  // real state updates via parent state
}
```

